def _admin_application_detail_page(ir: FrontendIR) -> str:
    """Application review page — renders submitted fields and approve/reject.

    Uses the cached ``useListApplications`` query to locate the application
    by id (avoids a second roundtrip when the admin navigated here from the
    dashboard or applications list). Falls back to a clear empty state if
    the id is unknown — e.g. someone navigated directly via URL after the
    application was approved/rejected and dropped from the active filter.
    """
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
"use client";

import {{ use, useMemo, useState }} from "react";
import Link from "next/link";
import {{ Card, CardContent, CardHeader, CardTitle }} from "@/components/ui/card";
import {{ Button }} from "@/components/ui/button";
import {{ Badge }} from "@/components/ui/badge";
import {{
  useApproveApplication,
  useListApplicationFiles,
  useListApplications,
  useRejectApplication,
}} from "@/generated/hooks/use-admin";

interface ApplicationFile {{
  id: string;
  filename: string;
  size_bytes?: number;
  content_type?: string;
  category?: string;
  url?: string;
  created_at?: string;
}}

interface ApplicationDetail {{
  _id?: string;
  id?: string;
  status?: string;
  applicant_email?: string;
  participant_type?: string;
  submitted_at?: string;
  created_at?: string;
  submitted_completeness?: number;
  submitted_fields?: Record<string, unknown>;
  admin_feedback?: string | null;
  user_id?: string | null;
}}

function statusVariant(status?: string): "default" | "secondary" | "destructive" | "outline" {{
  if (status === "approved") return "default";
  if (status === "rejected") return "destructive";
  if (status === "pending") return "secondary";
  return "outline";
}}

function renderFieldValue(value: unknown): string {{
  if (value === null || value === undefined) return "—";
  if (Array.isArray(value)) return value.map((v) => String(v)).join(", ");
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}}

export default function AdminApplicationDetailPage({{
  params,
}}: {{
  params: Promise<{{ id: string }}>
}}) {{
  const {{ id }} = use(params);
  const applications = useListApplications();
  const approve = useApproveApplication();
  const reject = useRejectApplication();
  const filesQuery = useListApplicationFiles(id);
  const [feedback, setFeedback] = useState("");

  const application = useMemo<ApplicationDetail | null>(() => {{
    if (!Array.isArray(applications.data)) return null;
    return (
      (applications.data as ApplicationDetail[]).find(
        (row) => String(row._id ?? row.id ?? "") === id,
      ) ?? null
    );
  }}, [applications.data, id]);

  const uploadedFiles: ApplicationFile[] = useMemo(() => {{
    return Array.isArray(filesQuery.data)
      ? (filesQuery.data as unknown as ApplicationFile[])
      : [];
  }}, [filesQuery.data]);

  function formatBytes(n?: number): string {{
    if (typeof n !== "number" || n <= 0) return "—";
    if (n < 1024) return `${{n}} B`;
    if (n < 1024 * 1024) return `${{Math.round(n / 1024)}} KB`;
    return `${{(n / (1024 * 1024)).toFixed(1)}} MB`;
  }}

  if (applications.isLoading && !application) {{
    return <p className="text-sm text-muted-foreground">Loading application…</p>;
  }}

  if (applications.error) {{
    return (
      <div className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
        Failed to load applications: {{applications.error.message}}
      </div>
    );
  }}

  if (!application) {{
    return (
      <div className="space-y-4">
        <Link href="/admin/applications" className="text-sm text-primary hover:underline">
          ← Back to applications
        </Link>
        <Card>
          <CardContent className="py-8 text-center text-sm text-muted-foreground">
            Application <code className="font-mono text-xs">{{id}}</code> not found.
            It may have been deleted, or your applications list is filtered.
          </CardContent>
        </Card>
      </div>
    );
  }}

  const submittedAt = application.submitted_at ?? application.created_at;
  const fieldEntries = Object.entries(application.submitted_fields ?? {{}});
  const isPending = application.status === "pending";

  // After a successful approve, the backend returns a one-shot
  // ``temporary_password`` so the admin can read it out (Resend can't deliver
  // to arbitrary recipients in sandbox). Surface it as a prominent banner.
  const approveResult = approve.data as
    | {{ applicant_email?: string; temporary_password?: string; status?: string }}
    | undefined;
  const hasGeneratedCredentials = Boolean(
    approveResult?.temporary_password && approveResult?.applicant_email,
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-2">
        <Link href="/admin/applications" className="text-sm text-primary hover:underline">
          ← Back to applications
        </Link>
      </div>

      {{hasGeneratedCredentials && (
        <Card className="animate-fade-in-up border-emerald-500/40 bg-emerald-500/5">
          <CardHeader>
            <CardTitle className="text-emerald-700 dark:text-emerald-300">
              ✅ Application approved — credentials generated
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3 text-sm">
            <p className="text-muted-foreground">
              A welcome email was queued, but if delivery fails you can share
              these credentials with the applicant directly. They appear once;
              copy them now.
            </p>
            <dl className="grid gap-3 sm:grid-cols-2">
              <div className="rounded-md border bg-background p-3">
                <dt className="text-xs uppercase text-muted-foreground">Email</dt>
                <dd className="mt-1 font-mono text-sm">{{approveResult?.applicant_email}}</dd>
              </div>
              <div className="rounded-md border bg-background p-3">
                <dt className="text-xs uppercase text-muted-foreground">Temporary password</dt>
                <dd className="mt-1 break-all font-mono text-sm">
                  {{approveResult?.temporary_password}}
                </dd>
              </div>
            </dl>
            <div className="flex gap-2">
              <Button
                size="sm"
                variant="outline"
                onClick={{() => {{
                  if (typeof navigator !== "undefined" && navigator.clipboard) {{
                    navigator.clipboard.writeText(
                      `${{approveResult?.applicant_email}} / ${{approveResult?.temporary_password}}`,
                    );
                  }}
                }}}}
              >
                Copy email / password
              </Button>
              <Button size="sm" variant="ghost" onClick={{() => approve.reset()}}>
                Dismiss
              </Button>
            </div>
            <p className="text-xs text-muted-foreground">
              Backed up at WARNING level in the API logs:
              <code className="ml-1">docker compose logs api</code>
            </p>
          </CardContent>
        </Card>
      )}}

      <Card className="animate-fade-in-up">
        <CardHeader className="space-y-2">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <CardTitle className="text-2xl">{{application.applicant_email ?? "(no email)"}}</CardTitle>
            <div className="flex items-center gap-2">
              <Badge variant={{statusVariant(application.status)}}>{{application.status ?? "pending"}}</Badge>
              <Badge variant="outline" className="capitalize">
                {{application.participant_type ?? "—"}}
              </Badge>
            </div>
          </div>
          <p className="text-sm text-muted-foreground">
            {{submittedAt ? `Submitted ${{new Date(submittedAt).toLocaleString()}}` : ""}}
            {{typeof application.submitted_completeness === "number"
              ? ` · ${{application.submitted_completeness}}% complete`
              : ""}}
          </p>
          {{application.admin_feedback && (
            <p className="rounded-md bg-muted/60 px-3 py-2 text-sm">
              <span className="font-medium">Existing admin feedback:</span> {{application.admin_feedback}}
            </p>
          )}}
        </CardHeader>
      </Card>

      <Card className="animate-fade-in-up" style={{{{ animationDelay: "60ms" }}}}>
        <CardHeader>
          <CardTitle>Submitted information</CardTitle>
        </CardHeader>
        <CardContent>
          {{fieldEntries.length === 0 ? (
            <p className="text-sm text-muted-foreground">No fields submitted.</p>
          ) : (
            <dl className="grid gap-4 sm:grid-cols-2">
              {{fieldEntries.map(([key, value]) => (
                <div key={{key}} className="rounded-md border bg-muted/40 p-3">
                  <dt className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                    {{key.replace(/_/g, " ")}}
                  </dt>
                  <dd className="mt-1 break-words text-sm">{{renderFieldValue(value)}}</dd>
                </div>
              ))}}
            </dl>
          )}}
        </CardContent>
      </Card>

      <Card className="animate-fade-in-up" style={{{{ animationDelay: "90ms" }}}}>
        <CardHeader>
          <CardTitle>
            Uploaded documents
            {{!filesQuery.isLoading && (
              <span className="ml-2 text-sm font-normal text-muted-foreground">
                ({{uploadedFiles.length}})
              </span>
            )}}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {{filesQuery.isLoading ? (
            <p className="text-sm text-muted-foreground">Loading files…</p>
          ) : filesQuery.error ? (
            <p className="text-sm text-destructive">{{filesQuery.error.message}}</p>
          ) : uploadedFiles.length === 0 ? (
            <p className="py-4 text-center text-sm text-muted-foreground">
              No files uploaded with this application.
            </p>
          ) : (
            <ul className="divide-y rounded-md border">
              {{uploadedFiles.map((doc) => (
                <li key={{doc.id}} className="flex items-center justify-between gap-3 p-3">
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium">📎 {{doc.filename}}</p>
                    <p className="text-xs text-muted-foreground">
                      {{formatBytes(doc.size_bytes)}}
                      {{doc.content_type ? ` · ${{doc.content_type}}` : ""}}
                      {{doc.category ? ` · ${{doc.category}}` : ""}}
                    </p>
                  </div>
                  {{doc.url && (
                    <a
                      href={{doc.url}}
                      target="_blank"
                      rel="noreferrer"
                      className="inline-flex items-center justify-center rounded-md border px-3 py-1 text-sm hover:bg-muted"
                    >
                      View
                    </a>
                  )}}
                </li>
              ))}}
            </ul>
          )}}
        </CardContent>
      </Card>

      {{isPending ? (
        <Card className="animate-fade-in-up" style={{{{ animationDelay: "120ms" }}}}>
          <CardHeader>
            <CardTitle>Decision</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <textarea
              value={{feedback}}
              onChange={{(e) => setFeedback(e.target.value)}}
              rows={{3}}
              className="w-full rounded-md border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
              placeholder="Optional feedback for the applicant (shown on rejection emails)"
            />
            <div className="flex flex-wrap gap-2">
              <Button
                onClick={{() => approve.mutate(id as Parameters<typeof approve.mutate>[0])}}
                disabled={{approve.isPending}}
              >
                Approve application
              </Button>
              <Button
                variant="destructive"
                onClick={{() =>
                  reject.mutate({{
                    app_id: id,
                    body: {{ feedback }},
                  }} as unknown as Parameters<typeof reject.mutate>[0])
                }}
                disabled={{reject.isPending}}
              >
                Reject application
              </Button>
            </div>
            {{(approve.error || reject.error) && (
              <p className="text-sm text-destructive">
                {{approve.error?.message ?? reject.error?.message}}
              </p>
            )}}
          </CardContent>
        </Card>
      ) : (
        <Card className="animate-fade-in-up" style={{{{ animationDelay: "120ms" }}}}>
          <CardHeader>
            <CardTitle>Decision history</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-sm text-muted-foreground">
              This application is{{" "}}
              <span className="font-medium">{{application.status ?? "—"}}</span>.
              {{application.user_id
                ? " A profile has been created for this user."
                : " No further action available."}}
            </p>
          </CardContent>
        </Card>
      )}}
    </div>
  );
}}
"""


def _account_page(ir: FrontendIR) -> str:
    """Lightweight account page: email display + change-password form.

    Used primarily by admins (no participant profile to onboard). The route
    is also reachable by participants if they prefer not to navigate via
    ``/profile``, but the sidebar only surfaces it for admin users.
    """
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
"use client";

import {{ useState }} from "react";
import {{ Card, CardContent, CardDescription, CardHeader, CardTitle }} from "@/components/ui/card";
import {{ Button }} from "@/components/ui/button";
import {{ Input }} from "@/components/ui/input";
import {{ Label }} from "@/components/ui/label";
import {{ Badge }} from "@/components/ui/badge";
import {{ useAuth }} from "@/generated/hooks/use-current-user";
import {{ useChangePassword }} from "@/generated/hooks/use-auth";

export default function AccountPage() {{
  const {{ user, isLoading: authLoading }} = useAuth();
  const changePassword = useChangePassword();

  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  function clearForm() {{
    setCurrentPassword("");
    setNewPassword("");
    setConfirmPassword("");
  }}

  async function handleSubmit(event: React.FormEvent) {{
    event.preventDefault();
    setStatusMessage(null);
    setErrorMessage(null);

    if (!currentPassword) {{
      setErrorMessage("Enter your current password.");
      return;
    }}
    if (newPassword.length < 8) {{
      setErrorMessage("New password must be at least 8 characters.");
      return;
    }}
    if (newPassword !== confirmPassword) {{
      setErrorMessage("New password and confirmation don't match.");
      return;
    }}
    if (newPassword === currentPassword) {{
      setErrorMessage("New password must differ from the current one.");
      return;
    }}

    try {{
      await changePassword.mutateAsync({{
        current_password: currentPassword,
        new_password: newPassword,
      }} as Parameters<typeof changePassword.mutateAsync>[0]);
      setStatusMessage("Password updated. Use the new password next time you sign in.");
      clearForm();
    }} catch (err) {{
      const message = err instanceof Error ? err.message : "Failed to change password.";
      setErrorMessage(message);
    }}
  }}

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Account</h1>
        <p className="text-muted-foreground">Manage the credentials for your {ir.marketplace.name} account.</p>
      </div>

      <Card className="animate-fade-in-up">
        <CardHeader>
          <CardTitle>Account details</CardTitle>
          <CardDescription>Read-only — change-password is below.</CardDescription>
        </CardHeader>
        <CardContent>
          {{authLoading ? (
            <p className="text-sm text-muted-foreground">Loading…</p>
          ) : user ? (
            <dl className="grid gap-3 sm:grid-cols-2">
              <div>
                <dt className="text-xs uppercase text-muted-foreground">Email</dt>
                <dd className="mt-1 break-words text-sm font-medium">{{user.email}}</dd>
              </div>
              <div>
                <dt className="text-xs uppercase text-muted-foreground">Role</dt>
                <dd className="mt-1">
                  <Badge variant={{user.role === "admin" ? "default" : "secondary"}}>
                    {{user.role}}
                  </Badge>
                </dd>
              </div>
            </dl>
          ) : (
            <p className="text-sm text-muted-foreground">Not signed in.</p>
          )}}
        </CardContent>
      </Card>

      <Card className="animate-fade-in-up" style={{{{ animationDelay: "60ms" }}}}>
        <CardHeader>
          <CardTitle>Change password</CardTitle>
          <CardDescription>Use at least 8 characters. The new password must differ from the current one.</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={{handleSubmit}} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="current-password">Current password</Label>
              <Input
                id="current-password"
                type="password"
                autoComplete="current-password"
                value={{currentPassword}}
                onChange={{(e) => setCurrentPassword(e.target.value)}}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="new-password">New password</Label>
              <Input
                id="new-password"
                type="password"
                autoComplete="new-password"
                value={{newPassword}}
                onChange={{(e) => setNewPassword(e.target.value)}}
                required
                minLength={{8}}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="confirm-password">Confirm new password</Label>
              <Input
                id="confirm-password"
                type="password"
                autoComplete="new-password"
                value={{confirmPassword}}
                onChange={{(e) => setConfirmPassword(e.target.value)}}
                required
                minLength={{8}}
              />
            </div>

            {{errorMessage && (
              <div className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
                {{errorMessage}}
              </div>
            )}}
            {{statusMessage && (
              <div className="rounded-md bg-emerald-500/10 p-3 text-sm text-emerald-800 dark:text-emerald-200">
                {{statusMessage}}
              </div>
            )}}

            <div className="flex justify-end">
              <Button type="submit" disabled={{changePassword.isPending}}>
                {{changePassword.isPending ? "Updating…" : "Update password"}}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}}
"""
